mapper.select:
SELECT T.authority, T.alias, (CASE WHEN T.GROUP_ID IS NULL THEN 'default' ELSE T.GROUP_ID END) AS groupId
FROM LA_ROLES T WHERE ENABLED = 1

    AND T.AUTHORITY NOT IN #{item}



        AND T.TENANT_ID = #{tenant_id}


        AND T.TENANT_ID IS NULL


ORDER BY T.ALIAS

SELECT T.authority, T.alias, T.tenantId, T.enabled,T.roleType,T.dataType, T.icon, T.remarks, T.createDate, CASE WHEN T.GROUP_ID IS NULL THEN 'default' ELSE T.GROUP_ID END GROUP_ID
FROM LA_ROLES T


        AND T.AUTHORITY NOT IN #{item}


        AND T.GROUP_ID = #{parameters.groupId}


        AND T.ALIAS LIKE #{parameters.alias}



            AND T.TENANT_ID = #{parameters.tenantId}


            AND T.TENANT_ID IS NULL



ORDER BY T.ALIAS

mapper.delete:
DELETE FROM LA_ROLE_RESOURCES WHERE authority = #{authority}
AND resourceid IN

    #{item}

mapper.select:
SELECT id FROM LA_RESOURCES T
INNER JOIN LA_ROLE_RESOURCES TR ON T.ID = TR.RESOURCEID AND TR.AUTHORITY = #{authority}


        T.PARENTID IS NULL


        T.PARENTID = #{pid}

SELECT T.id, T.name, T.parentId, MAX(CASE WHEN T4.RESOURCEID IS NOT NULL THEN 1 ELSE 0 END) AS checked, COUNT(T2.ID) AS counts, SUM(CASE WHEN T3.RESOURCEID IS NULL THEN 0 ELSE 1 END) AS existed FROM LA_RESOURCES T LEFT JOIN LA_RESOURCES T2 ON T2.PARENTID = T.ID LEFT JOIN LA_ORGANIZATION_RESOURCES T3 ON T3.RESOURCEID = T2.ID AND T3.ORGANIZATIONID = #{organizationid} LEFT JOIN LA_ORGANIZATION_RESOURCES T4 ON T4.RESOURCEID = T.ID AND T4.ORGANIZATIONID = #{organizationid}
T.PARENTID IS NULL
T.PARENTID = #{pid}
GROUP BY T.ID, T.NAME, T.PARENTID, T.ORDERNO ORDER BY T.ORDERNO

SELECT DISTINCT T.id, T.res_name, T.parentId, T.res_rank, T.res_type, (CASE WHEN T3.RESOURCEID IS NOT NULL THEN 1 ELSE 0 END ) AS checked, T3.la_manage, T.orderno FROM LA_RESOURCES T
INNER JOIN LA_ROLE_RESOURCES T2 ON T2.RESOURCEID = T.ID AND T2.LA_MANAGE = 1
LEFT JOIN LA_ROLE_RESOURCES T3 ON T3.RESOURCEID = T.ID AND T3.AUTHORITY = #{parameters.authority} WHERE T.DEV = 0 AND T.res_type != 0 AND T.res_mode = #{parameters.mode}
AND T2.AUTHORITY IN
#{item}
ORDER BY T.res_rank, T.parentid, T.orderno

mapper.delete:
DELETE FROM LA_ROLE_RESOURCES WHERE authority IN (SELECT AUTHORITY FROM LA_ROLES WHERE TENANT_ID IN
    #{item}
)
